import YAML from 'yaml';

/**
 * Deterministic text edits for the reviewed catalog inputs. Generated catalog output
 * (apps.yaml and cluster.yaml, both copies) is only touched by appending or removing
 * whole documents; the rest is regenerated by `node scripts/curate-structure.cjs`.
 * Every function throws when its anchor is missing, so a changed file layout fails the
 * template loudly instead of producing a wrong PR.
 */

const PORTAL = 'services/onemind-portal';
export const PATHS = {
  workloadMap: `${PORTAL}/catalog/workload-map.yaml`,
  structure: `${PORTAL}/catalog/structure.yaml`,
  refBaseline: `${PORTAL}/catalog/ref-baseline.json`,
  apps: [
    `${PORTAL}/catalog/apps.yaml`,
    'platform/backstage/catalog/apps.yaml',
  ],
  cluster: [
    `${PORTAL}/catalog/cluster.yaml`,
    'platform/backstage/catalog/cluster.yaml',
  ],
  coverageExceptions: `${PORTAL}/catalog/coverage-exceptions.yaml`,
  structureTest: `${PORTAL}/scripts/test-catalog-structure.cjs`,
  coverageTest: `${PORTAL}/scripts/test-coverage.cjs`,
  stack: 'docs/STACK.md',
};

const escapeRe = (value: string) =>
  value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function insertBefore(text: string, anchor: RegExp, insertion: string) {
  const match = anchor.exec(text);
  if (!match) throw new Error(`Anchor ${anchor} not found`);
  return text.slice(0, match.index) + insertion + text.slice(match.index);
}

function insertAfter(text: string, anchor: RegExp, insertion: string) {
  const match = anchor.exec(text);
  if (!match) throw new Error(`Anchor ${anchor} not found`);
  const end = match.index + match[0].length;
  return text.slice(0, end) + insertion + text.slice(end);
}

/** Lines of a top-level section, from its header to the next top-level key. */
function sectionRange(text: string, key: string) {
  const header = new RegExp(`^${escapeRe(key)}:.*$`, 'm').exec(text);
  if (!header) throw new Error(`Section ${key} not found`);
  const start = header.index + header[0].length + 1;
  const next = /^[A-Za-z]/m.exec(text.slice(start));
  return { start, end: next ? start + next.index : text.length };
}

// --- additions (Add app) ----------------------------------------------------------

export function addArgoMapping(text: string, argoApp: string, ref: string) {
  return insertBefore(
    text,
    /^primaryArgoApplication:/m,
    `  ${argoApp}: ${ref}\n`,
  );
}

export type NewApp = {
  name: string;
  title: string;
  system: string;
  description: string;
};

export function addStructureApp(text: string, app: NewApp) {
  const block = YAML.stringify([
    {
      name: app.name,
      title: app.title,
      system: app.system,
      description: app.description,
    },
  ])
    .trimEnd()
    .split('\n')
    .map(line => `  ${line}`)
    .join('\n');
  return insertBefore(text, /^placement:/m, `${block}\n`);
}

export function addPlacement(text: string, name: string, system: string) {
  return insertAfter(text, /^placement:[^\n]*\n/m, `  ${name}: ${system}\n`);
}

export function addPillarOverride(text: string, ref: string, pillar: string) {
  if (/^pillarOverrides: \{\}\s*$/m.test(text)) {
    return text.replace(
      /^pillarOverrides: \{\}\s*$/m,
      `pillarOverrides:\n  ${ref}: ${pillar}`,
    );
  }
  return insertAfter(
    text,
    /^pillarOverrides:[^\n]*\n/m,
    `  ${ref}: ${pillar}\n`,
  );
}

/** Appends one document in the exact format the catalog generators write. */
export function appendCatalogDocument(text: string, entity: object) {
  const body = text.endsWith('\n') ? text : `${text}\n`;
  return `${body}---\n${YAML.stringify(entity)}`;
}

export function appendSection(markdown: string, section: string) {
  const body = markdown.endsWith('\n') ? markdown : `${markdown}\n`;
  return `${body}\n${section.trimEnd()}\n`;
}

export function systemPillar(structure: string, system: string) {
  const parsed = YAML.parse(structure);
  const found = (parsed.systems ?? []).find((s: any) => s.name === system);
  return found ? (found.pillar as string | undefined) : undefined;
}

export function systemNames(structure: string): string[] {
  const parsed = YAML.parse(structure);
  return (parsed.systems ?? []).map((s: any) => String(s.name));
}

// --- removals (Retire app) ---------------------------------------------------------

export function removeMapEntries(
  text: string,
  o: { ref: string; keys: string[] },
) {
  const removed: string[] = [];
  const keys = new Set(o.keys);
  const lines = text.split('\n').filter(line => {
    const m = /^ {2}([^\s:][^:]*): (\S+)\s*$/.exec(line);
    if (m && keys.has(m[1]) && m[2] === o.ref) {
      removed.push(m[1]);
      return false;
    }
    return true;
  });
  return { text: lines.join('\n'), removed };
}

/** `primaryArgoApplication` is keyed by the app name, whatever its value. */
export function removePrimaryArgo(text: string, appName: string) {
  const { start, end } = sectionRange(text, 'primaryArgoApplication');
  const body = text.slice(start, end);
  const re = new RegExp(`^ {2}${escapeRe(appName)}: .*\\n`, 'm');
  if (!re.test(body)) return text;
  return text.slice(0, start) + body.replace(re, '') + text.slice(end);
}

export function removeStructureApp(text: string, name: string) {
  const { start, end } = sectionRange(text, 'apps');
  const body = text.slice(start, end);
  const item = new RegExp(
    `^ {2}- name: ${escapeRe(name)}\\n(?: {4}.*\\n)*`,
    'm',
  );
  const next = body.replace(item, '');
  let out = next === body ? text : text.slice(0, start) + next + text.slice(end);
  for (const [section, key] of [
    ['placement', name],
    ['titles', `component:default/${name}`],
    ['pillarOverrides', `component:default/${name}`],
  ] as const) {
    if (!new RegExp(`^${section}:`, 'm').test(out)) continue;
    const range = sectionRange(out, section);
    const part = out.slice(range.start, range.end);
    const cleaned = part.replace(
      new RegExp(`^ {2}${escapeRe(key)}: .*\\n`, 'm'),
      '',
    );
    out = out.slice(0, range.start) + cleaned + out.slice(range.end);
  }
  return out;
}

export function removeRefBaseline(text: string, refs: string[]) {
  const parsed = JSON.parse(text);
  const indent = /\n( +)"/.exec(text)?.[1].length ?? 2;
  const render = (value: unknown) => `${JSON.stringify(value, null, indent)}\n`;
  if (render(parsed) !== text) return undefined;
  const drop = new Set(refs);
  parsed.refs = parsed.refs.filter((ref: string) => !drop.has(ref));
  return render(parsed);
}

/**
 * The portal tests hard-code how many Argo applications Git defines. Returns the new
 * text, or undefined when a pattern no longer matches (the checklist then names the
 * file so a person updates it).
 */
export function bumpStructureTestCount(text: string, delta: number) {
  const re =
    /(assert\.equal\(inGit\.size, )(\d+)(, 'platform\/ should define the )(\d+)( source Argo applications'\))/;
  const m = re.exec(text);
  if (!m || m[2] !== m[4]) return undefined;
  const next = String(Number(m[2]) + delta);
  return text.replace(re, `$1${next}$3${next}$5`);
}

export function bumpCoverageTestCount(text: string, delta: number) {
  const eq = /(assert\.equal\(report\.argoApplicationsLinked, )(\d+)(\))/;
  const note = /(\/\/ All )(\d+)( Argo applications are linked)/;
  const a = eq.exec(text);
  const b = note.exec(text);
  if (!a || !b || a[2] !== b[2]) return undefined;
  const next = String(Number(a[2]) + delta);
  return text.replace(eq, `$1${next}$3`).replace(note, `$1${next}$3`);
}

export function currentArgoCount(structureTest: string): number | undefined {
  const m = /assert\.equal\(inGit\.size, (\d+),/.exec(structureTest);
  return m ? Number(m[1]) : undefined;
}

/**
 * A staged app has an Argo application and no live workload yet, so the coverage audit
 * would fail on three capabilities. The repository's pattern (ThingsBoard, Karakeep) is a
 * reviewed preparation exception; the audit turns stale once real coverage exists, which
 * is the reminder to delete it.
 */
export function addPreparationExceptions(text: string, name: string, title: string) {
  const reason = `${title} source is staged with a manual Argo Application and no live namespace or workload snapshot is recorded.\n      Generate this scoped coverage only after deployment is observed, then remove this preparation exception.`;
  const body = text.endsWith('\n') ? text : `${text}\n`;
  return (
    body +
    ['kubernetes', 'grafana-alerts', 'logs']
      .map(
        capability =>
          `  - app: component:default/${name}\n    capability: ${capability}\n    reason: >-\n      ${reason}\n`,
      )
      .join('')
  );
}

export function removeCoverageExceptions(text: string, ref: string) {
  const re = new RegExp(
    `^ {2}- app: ${escapeRe(ref)}\\n(?: {4,}.*\\n)*`,
    'gm',
  );
  return text.replace(re, '');
}
